"""Dependency-free interactive Chinese HTML renderer for daily report bundles.

The renderer intentionally performs formatting and chart interaction only. All
strategy states, breakout assessments and entry conclusions are calculated by
the application layer before this module receives the serialized bundle.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import TYPE_CHECKING, Any, Mapping

if TYPE_CHECKING:
    from inv_trend.application.daily_models import InstrumentReportBundle


def write_instrument_report(
    bundle: InstrumentReportBundle | Mapping[str, Any],
    path: str | Path,
) -> Path:
    # The presentation layer accepts a serialized report bundle and does not
    # need to import its application DTO at runtime.  This keeps renderer
    # composition independent of application-package initialization order.
    to_dict = getattr(bundle, "to_dict", None)
    payload = to_dict() if callable(to_dict) else dict(bundle)
    snapshot = {
        "report_date": str(payload.get("generated_at", ""))[:10],
        "timeframe": payload.get("timeframe", "D1"),
        "symbols": [
            {
                "symbol": payload.get("symbol", "?"),
                "run_status": "updated",
                "report_bundle": payload,
            }
        ],
        "summary": payload.get("summary", {}),
    }
    return _write(render_daily_dashboard(snapshot), path)


def write_daily_dashboard(snapshot: Mapping[str, Any], path: str | Path) -> Path:
    return _write(render_daily_dashboard(snapshot), path)


def render_daily_dashboard(snapshot: Mapping[str, Any]) -> str:
    payload = json.dumps(snapshot, ensure_ascii=False, allow_nan=False, default=str)
    payload = payload.replace("</", "<\\/")
    title = f"趋势策略每日分析报告 {snapshot.get('report_date', '')}".strip()
    return f"""<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>{_html_text(title)}</title>
<style>{_CSS}</style>
</head>
<body>
<header class="topbar">
  <div><div class="eyebrow">INV TREND · 中文金融分析日报</div><h1>{_html_text(title)}</h1></div>
  <label class="selector-wrap" for="symbolSelect">分析标的 <select id="symbolSelect"></select></label>
</header>
<main>
  <section id="identity" class="identity" aria-label="标的和数据身份"></section>
  <section id="dataStatusPanel" class="panel data-panel" aria-label="数据状态与就绪性"></section>
  <section id="screeningPanel" class="panel data-panel" aria-label="策略筛选"></section>
  <section id="decisionPanel" class="decision-grid" aria-label="最终趋势与执行状态"></section>

  <section class="panel breakout-panel">
    <div class="section-head"><div><span class="kicker">突破信号</span><h2>突破与入场判断</h2></div><p class="section-note">突破并不等同于入场；仅同向 A 级共振显示做多或做空。</p></div>
    <div class="table-wrap"><table class="breakout-table"><thead><tr>
      <th>时间</th><th>当前价格</th><th>突破类型</th><th>突破对象</th><th>突破前状态</th><th>突破后状态</th>
      <th>趋势判断</th><th>入场方向</th><th>信号强度</th><th>触发依据</th><th>未满足条件</th><th>结论</th><th>图表</th>
    </tr></thead><tbody id="breakoutRows"></tbody></table></div>
  </section>

  <section class="panel chart-panel">
    <div class="section-head"><div><span class="kicker">图表联动</span><h2>价格、突破、异常与指标</h2></div><div id="hoverInfo" class="hover-info">移动鼠标查看同一时间点；点击突破标记可定位表格。</div></div>
    <div class="range-row"><label for="rangeStart">显示起点</label><input id="rangeStart" type="range" min="0" value="0"><span id="rangeLabel"></span></div>
    <div class="legend" id="priceLegend"></div><canvas id="priceChart" height="330" aria-label="价格与突破图"></canvas>
    <div class="legend" id="macdLegend"></div><canvas id="macdChart" height="165" aria-label="MACD 图"></canvas>
    <div class="legend" id="trendLegend"></div><canvas id="trendChart" height="165" aria-label="趋势质量图"></canvas>
    <div class="legend" id="volLegend"></div><canvas id="volChart" height="165" aria-label="波动与量能图"></canvas>
  </section>

  <section class="panel"><div class="section-head"><div><span class="kicker">触发依据</span><h2>策略条件明细</h2></div><div id="conditionStats" class="hover-info"></div></div><div id="ruleList" class="rules"></div></section>
  <section class="panel"><div class="section-head"><div><span class="kicker">指标详情</span><h2>多维趋势检查</h2></div></div><div class="table-wrap"><table><thead><tr><th>策略维度</th><th>状态</th><th>方向</th><th>数值与说明</th></tr></thead><tbody id="indicatorRows"></tbody></table></div></section>
  <section class="split">
    <section class="panel"><div class="section-head"><div><span class="kicker">其他事件</span><h2>均线与 MACD 事件</h2></div></div><div class="table-wrap"><table><thead><tr><th>时间</th><th>事件</th><th>方向</th><th>价格</th></tr></thead><tbody id="signalRows"></tbody></table></div></section>
    <section class="panel"><div class="section-head"><div><span class="kicker">异常</span><h2>异常点</h2></div></div><div class="table-wrap"><table><thead><tr><th>时间</th><th>类型</th><th>级别</th><th>依据</th></tr></thead><tbody id="anomalyRows"></tbody></table></div></section>
  </section>
  <details class="panel"><summary>状态变更与技术说明</summary><div class="details-body"><div class="table-wrap"><table><thead><tr><th>时间</th><th>状态</th><th>变更前</th><th>变更后</th><th>原因</th></tr></thead><tbody id="transitionRows"></tbody></table></div><div class="table-wrap"><table><thead><tr><th>模块</th><th>修改内容</th><th>原因</th><th>效果</th></tr></thead><tbody id="changeRows"></tbody></table></div></div></details>
  <details class="panel"><summary>机器可读 ReportBundle</summary><pre id="rawJson"></pre></details>
</main>
<footer>图表、突破表、条件、异常和策略状态均来自同一份 ReportBundle。HTML 只做中文展示和联动，不重新计算交易逻辑；本报告不构成投资建议。</footer>
<script id="snapshot" type="application/json">{payload}</script>
<script>{_JS}</script>
</body></html>"""


def _write(document: str, path: str | Path) -> Path:
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(document, encoding="utf-8")
    return target


def _html_text(value: Any) -> str:
    return (
        str(value)
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace('"', "&quot;")
    )


_CSS = r"""
:root{color-scheme:dark;--bg:#071019;--panel:#0d1824;--panel2:#111f2e;--line:#24364a;--text:#e7eef7;--muted:#8ca0b6;--ok:#4ade80;--bad:#fb7185;--warn:#fbbf24;--info:#60a5fa;font:14px Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 12% 0,#122235 0,#071019 42%);color:var(--text)}.topbar{position:sticky;top:0;z-index:5;display:flex;justify-content:space-between;align-items:end;gap:24px;padding:22px max(24px,calc((100vw - 1320px)/2));background:rgba(7,16,25,.94);backdrop-filter:blur(12px);border-bottom:1px solid var(--line)}h1,h2{margin:0}.eyebrow,.kicker{font-size:11px;letter-spacing:.12em;color:#67e8f9;font-weight:700}.topbar h1{margin-top:6px;font-size:26px}.selector-wrap{display:flex;align-items:center;gap:9px;color:var(--muted)}select,input{accent-color:#67e8f9;background:#0a1420;color:var(--text);border:1px solid var(--line);border-radius:8px;padding:8px}main{max-width:1320px;margin:auto;padding:22px 24px}.identity{display:flex;gap:9px;flex-wrap:wrap;margin-bottom:12px}.pill{padding:6px 9px;border:1px solid var(--line);border-radius:999px;background:#0b1723;color:var(--muted);font-size:12px}.pill b{color:var(--text)}.decision-grid{display:grid;grid-template-columns:1.05fr 1fr 1.2fr;gap:12px}.decision{background:linear-gradient(155deg,var(--panel2),var(--panel));border:1px solid var(--line);border-top:3px solid var(--info);border-radius:14px;padding:15px}.decision.trend{border-top-color:#a78bfa}.decision.entry{border-top-color:var(--warn)}.decision h2{font-size:23px;margin:7px 0}.decision p{margin:5px 0;color:var(--muted);line-height:1.55}.basis{margin:9px 0 0;padding-left:17px;color:#b8c8d8;font-size:12px;line-height:1.65}.panel{background:rgba(13,24,36,.96);border:1px solid var(--line);border-radius:15px;padding:16px;margin:16px 0;box-shadow:0 14px 42px rgba(0,0,0,.14)}.data-panel{padding:12px 16px;color:var(--muted)}.section-head{display:flex;justify-content:space-between;align-items:end;gap:16px;margin-bottom:12px}.section-head h2{font-size:18px;margin-top:4px}.section-note,.hover-info{margin:0;color:var(--muted);font-size:12px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:680px}th,td{text-align:left;padding:9px 10px;border-bottom:1px solid var(--line);vertical-align:top}th{color:#a8bed4;font-size:12px;white-space:nowrap}td{color:#d9e4ef}.breakout-table{min-width:1740px}.breakout-table tr.selected{background:#14263a}.compact-list{margin:0;padding-left:17px;min-width:170px;max-width:265px;font-size:12px;line-height:1.55}.compact-list.warn{color:#f6d38b}.compact-list.ok{color:#a7f3c1}.tag{display:inline-block;padding:3px 7px;border-radius:999px;border:1px solid var(--line);font-size:12px;white-space:nowrap}.tag.long,.tag.entry-long{background:#082b18;border-color:#166534;color:var(--ok)}.tag.short,.tag.entry-short{background:#2c0d13;border-color:#7f1d1d;color:var(--bad)}.tag.no-entry,.tag.unknown{background:#291b06;border-color:#713f12;color:var(--warn)}button{border:1px solid var(--line);border-radius:7px;background:#10263c;color:#bdeafe;padding:5px 8px;cursor:pointer}button:hover{background:#173553}canvas{display:block;width:100%;background:#08131f;border:1px solid #1f3348;border-radius:10px;margin:6px 0 14px}.legend{display:flex;gap:13px;flex-wrap:wrap;color:var(--muted);font-size:12px}.legend i{width:18px;height:3px;border-radius:3px;display:inline-block;margin-right:5px;vertical-align:middle}.range-row{display:flex;align-items:center;gap:10px;margin:8px 0 12px;color:var(--muted)}.range-row input{flex:1;padding:0}.rules{display:grid;gap:8px}.rule{border:1px solid var(--line);border-radius:10px;background:#0a1521}.rule summary{cursor:pointer;display:flex;align-items:center;gap:10px;padding:11px;list-style:none}.rule summary::-webkit-details-marker{display:none}.rule-title{font-weight:700;flex:1}.badge{font-size:11px;padding:3px 7px;border-radius:999px;border:1px solid var(--line)}.badge.true{color:var(--ok);border-color:#166534;background:#082b18}.badge.false{color:var(--bad);border-color:#7f1d1d;background:#2c0d13}.badge.na{color:var(--warn);border-color:#713f12;background:#291b06}.conditions{padding:0 11px 11px;overflow:auto}.conditions table{min-width:960px}.split{display:grid;grid-template-columns:1fr 1fr;gap:16px}.split .panel{margin:0}.details-body{display:grid;gap:15px;margin-top:14px}pre{max-height:480px;overflow:auto;white-space:pre-wrap;color:#b9cce0}summary{cursor:pointer;font-weight:700}footer{max-width:1320px;margin:0 auto;padding:0 24px 32px;color:#6f849b;font-size:12px}@media(max-width:900px){.decision-grid,.split{grid-template-columns:1fr}.topbar{position:static;align-items:flex-start;flex-direction:column}.section-head{align-items:flex-start;flex-direction:column}main{padding:14px}.breakout-panel{padding:12px}.topbar h1{font-size:22px}}
"""


_JS = r"""
const SNAPSHOT=JSON.parse(document.getElementById('snapshot').textContent);
const rows=SNAPSHOT.symbols||[];
const select=document.getElementById('symbolSelect');
rows.forEach((row,index)=>{const option=document.createElement('option');option.value=index;option.textContent=`${row.symbol||row.report_bundle?.symbol||'?'}${row.report_bundle?'':'（数据不可用）'}`;select.appendChild(option)});
let currentRow=null,current=null,hoverIndex=null,startIndex=0,activeAssessmentId=null,priceMarkerHits=[];
const palette={close:'#e2e8f0',channel_high_20:'#38bdf8',channel_low_20:'#38bdf8',channel_high_55:'#a78bfa',channel_low_55:'#a78bfa',sma_10:'#4ade80',sma_20:'#fbbf24',ema_144:'#fb7185',ema_169:'#f97316',dif:'#4ade80',dea:'#fbbf24',adx:'#e2e8f0',plus_di:'#4ade80',minus_di:'#fb7185',atr_percentile:'#60a5fa',relative_volume:'#c084fc'};
const zh={long:'多头',short:'空头',none:'未形成',conflict:'方向冲突',ready:'已就绪',unavailable:'不可用',updated:'已更新',unchanged:'数据未变化',stale:'数据过期',failed:'扫描失败',blocked:'已阻塞',not_run:'未扫描',STALE_DATA:'数据过期',FRESH:'数据新鲜',normal:'正常',low:'偏低',high:'偏高',medium:'中',bullish:'多头共振',bearish:'空头共振',golden_cross:'金叉',death_cross:'死叉',alignment_formed:'排列形成',grade_a_entered:'进入 A 级',turtle_20:'海龟 20 日突破',turtle_55:'海龟 55 日突破',sma_10_20:'SMA10/20',macd_12_26_9:'MACD 12/26/9',sma_alignment:'SMA 排列',ema_trend:'EMA 趋势',strategy_rating:'策略评级',strategy_rating_a:'A 级共振',trend_quality:'ADX/DMI 趋势质量',volatility:'ATR 波动状态',volume:'相对成交量',above:'上方',below:'下方',inside:'区间内',entry_direction:'入场方向',rating_family:'评级策略族',rating_adjustment:'评级质量调整',final_rating:'最终评级',cross_signal:'交叉信号',report_only:'报告说明',strategy_rating:'策略评级',strategy_direction:'策略方向',volatility_state:'波动状态',large_price_move:'价格异动',range_expansion:'日内振幅异常',atr_percentile_extreme:'ATR 分位极端',MA_GOLDEN_CROSS_10_20:'SMA10/20 金叉',MA_DEATH_CROSS_10_20:'SMA10/20 死叉',MACD_GOLDEN_CROSS:'MACD 金叉',MACD_DEATH_CROSS:'MACD 死叉',STRATEGY_GRADE_A_LONG:'A 级多头共振',STRATEGY_GRADE_A_SHORT:'A 级空头共振'};
function esc(value){return String(value??'—').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
function label(value){return zh[String(value)]??String(value??'不可用')}
function fmt(value,digits=4){if(value===null||value===undefined||!Number.isFinite(Number(value)))return '—';const number=Number(value);return Math.abs(number)>=1000?number.toLocaleString(undefined,{maximumFractionDigits:2}):number.toFixed(digits).replace(/0+$/,'').replace(/\.$/,'')}
function shortTime(value){return value?String(value).replace('T',' ').replace('+00:00','Z'):'—'}
function badge(value){return `<span class="badge ${value===true?'true':value===false?'false':'na'}">${value===true?'满足':value===false?'未满足':'不可用'}</span>`}
function list(items,kind=''){const values=items||[];return values.length?`<ul class="compact-list ${kind}">${values.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:'<span class="hover-info">无</span>'}
function entryTag(value){const klass=value==='做多'?'entry-long':value==='做空'?'entry-short':'no-entry';return `<span class="tag ${klass}">${esc(value||'不入场')}</span>`}
function directionTag(value){const klass=value==='long'||value==='多头'?'long':value==='short'||value==='空头'?'short':'unknown';return `<span class="tag ${klass}">${esc(label(value))}</span>`}
function load(index){currentRow=rows[index]||{};current=currentRow.report_bundle||null;hoverIndex=null;activeAssessmentId=null;startIndex=0;const series=current?.series||[];const slider=document.getElementById('rangeStart');slider.max=Math.max(0,series.length-25);slider.value=0;renderAll()}
function renderAll(){renderIdentity();renderDataStatus();renderScreening();renderDecision();renderBreakouts();renderRules();renderIndicators();renderOtherTables();renderTechnicalDetails();renderRaw();renderCharts()}
function renderIdentity(){const bundle=current||{};const row=currentRow||{};const pairs=[['标的',row.symbol||bundle.symbol||'—'],['合约',bundle.instrument_id||row.instrument_id||row.instrument||'—'],['周期',bundle.timeframe||row.timeframe||'D1'],['数据版本',bundle.dataset_version||row.data?.dataset_version||'—'],['报告结果',bundle.result_id||'未生成'],['扫描状态',label(row.run_status)]];document.getElementById('identity').innerHTML=pairs.map(([name,value])=>`<span class="pill">${esc(name)}：<b>${esc(value)}</b></span>`).join('')}
function renderDecision(){const target=document.getElementById('decisionPanel');if(!current){target.innerHTML=`<article class="decision"><span class="kicker">市场状态</span><h2>无法生成报告</h2><p>${esc(rowError())}</p></article><article class="decision trend"><span class="kicker">趋势判断</span><h2>趋势不明确</h2><p>缺少可用的完整 D1 数据。</p></article><article class="decision entry"><span class="kicker">入场方向</span><h2>不入场</h2><p>未生成结构化策略结果。</p></article>`;return}const decision=current.trend_decision_result||currentRow.trend_decision_result||currentRow.stages?.trend_decision;if(decision?.result_hash){const direction=decision.trend_direction==='LONG'?'上升趋势':decision.trend_direction==='SHORT'?'下降趋势':'趋势不明确';const entry=decision.execution_state==='ENTER_LONG'?'做多':decision.execution_state==='ENTER_SHORT'?'做空':'不入场';const confidence=decision.confidence||{};const evidence=decision.trend_direction==='LONG'?decision.long_evidence:decision.trend_direction==='SHORT'?decision.short_evidence:decision.reverse_evidence;target.innerHTML=`<article class="decision"><span class="kicker">最终趋势 / 执行状态</span><h2>${esc(decision.decision||'WAIT')} · ${esc(decision.execution_state||'WAIT')}</h2><p>截至：${esc(shortTime(decision.as_of||current.latest_bar?.timestamp))}</p><p>${esc(decision.observation_only?'观察性结果，不执行。':'正式决策结果。')}</p></article><article class="decision trend"><span class="kicker">趋势判断</span><h2>${esc(direction)}</h2>${list(evidence||[])}</article><article class="decision entry"><span class="kicker">入场方向</span><h2>${entryTag(entry)}</h2><p>${esc(decision.conclusion||'等待结构化趋势决策。')}</p><p>策略评级：${esc(confidence.rating_grade||'—')} / ${esc(fmt(confidence.rating_score,1))} 分</p></article>`;return}const assessment=current.market_assessment||legacyMarketAssessment();target.innerHTML=`<article class="decision"><span class="kicker">市场状态</span><h2>${esc(assessment.market_status||'已生成报告')}</h2><p>截至：${esc(shortTime(assessment.as_of||current.latest_bar?.timestamp))}</p><p>数据状态：${esc(label(currentRow.run_status))}</p></article><article class="decision trend"><span class="kicker">趋势判断</span><h2>${esc(assessment.trend||'趋势不明确')}</h2>${list(assessment.trend_basis||[])}</article><article class="decision entry"><span class="kicker">入场方向</span><h2>${entryTag(assessment.entry_direction)}</h2><p>${esc(assessment.entry_reason||'报告未提供展示性入场结论。')}</p><p>策略评级：${esc(assessment.rating_grade||'—')} / ${esc(fmt(assessment.rating_score,1))} 分</p></article>`}
function legacyMarketAssessment(){const rating=current.strategy_snapshot?.strategy_checks?.rating||{};return {market_status:'旧版快照：仅可展示原始策略结果',trend:'趋势不明确',trend_basis:['该快照未包含结构化突破评估。'],entry_direction:'不入场',entry_reason:'请重新运行日报以生成结构化突破与入场判断。',rating_grade:rating.grade,rating_score:rating.score}}
function rowError(){const update=currentRow?.update||{};const detail=String(update.error||currentRow?.scan?.reason||'');if(!detail)return '当前标的没有可用于生成 ReportBundle 的数据。';if(detail.includes('no current dataset'))return `未找到当前 D1 数据集（${detail}）`;if(detail.includes('update_failed_no_current'))return '数据更新失败，且没有可用的历史数据集。';return `数据处理异常：${detail}`}
function renderDataStatus(){const target=document.getElementById('dataStatusPanel');const result=current?.data_update_result||currentRow?.data_update_result||currentRow?.stages?.data_update;if(result?.result_hash){const fresh=result.freshness||{};const quality=result.quality||{};const blockers=result.blocking_reasons||[];target.innerHTML=`<b>数据状态与就绪性：</b>${esc(result.data_readiness||'BLOCKED')}；最新完整 D1：${esc(shortTime(result.latest_complete_d1))}；质量：${esc((quality.statuses||[]).join('、')||'不可用')}；新鲜度：${esc(label(fresh.status))}；血缘：${result.lineage?.verified?'已验证':'未验证'}。${blockers.length?` 阻断原因：${esc(blockers.join('、'))}。`:''}`;return}if(!current){target.innerHTML=`<b>数据与异常说明：</b>${esc(rowError())}`;return}const fresh=currentRow.freshness||{};const update=currentRow.update||{};target.innerHTML=`<b>数据状态与就绪性：</b>${esc(label(currentRow.run_status))}；最新完整 K 线：${esc(shortTime(current.latest_bar?.timestamp||currentRow.data?.latest_complete_bar))}；新鲜度：${esc(label(fresh.status))}；更新状态：${esc(label(update.status||update.mode))}。`}
function renderScreening(){const target=document.getElementById('screeningPanel');const result=current?.strategy_screening_result||currentRow?.strategy_screening_result||currentRow?.stages?.strategy_screening;if(result?.result_hash){const eligibility=result.eligibility||{};target.innerHTML=`<b>策略筛选：</b>${esc(result.screening_status||'NOT_RUN')}；条件 ${esc((result.conditions||[]).length)} 项；规则 ${esc((result.rules||[]).length)} 项；原始事件 ${esc((result.raw_events||[]).length)} 个；海龟候选突破 ${esc((result.turtle_breakouts||[]).length)} 个；资格校验：${esc(eligibility.status||'NOT_EVALUATED')}。${result.reason?` ${esc(result.reason)}`:''}`;return}target.innerHTML='<b>策略筛选：</b>旧快照兼容展示；未包含独立阶段结果。'}
function renderBreakouts(){const target=document.getElementById('breakoutRows');if(!current){target.innerHTML='<tr><td colspan="13">该标的未生成结构化报告，无法展示突破判断。</td></tr>';return}const items=current.breakout_assessments||[];if(!items.length){target.innerHTML='<tr><td colspan="13">本次扫描或回放未检测到海龟 20/55 日价格突破。</td></tr>';return}target.innerHTML=items.map(item=>`<tr id="breakout-${esc(item.assessment_id)}" class="${item.assessment_id===activeAssessmentId?'selected':''}"><td>${esc(shortTime(item.timestamp))}</td><td>${fmt(item.current_price,2)}</td><td>${esc(item.breakout_type)}</td><td>${esc(item.breakout_object)}<br><small>参考位：${fmt(item.breakout_level,2)}</small></td><td>${esc(item.previous_state)}</td><td>${esc(item.post_state)}</td><td>${esc(item.trend)}${list(item.trend_basis||[])}</td><td>${entryTag(item.entry_direction)}</td><td>${esc(item.signal_strength)}</td><td>${list(item.triggered_conditions,'ok')}</td><td>${list([...(item.unmet_conditions||[]),...(item.quality_notes||[])],'warn')}</td><td>${esc(item.conclusion)}</td><td><button type="button" data-assessment="${esc(item.assessment_id)}">定位图表</button></td></tr>`).join('');target.querySelectorAll('button[data-assessment]').forEach(button=>button.addEventListener('click',()=>focusAssessment(button.dataset.assessment)))}
function focusAssessment(id){if(!current)return;activeAssessmentId=id;const item=(current.breakout_assessments||[]).find(value=>value.assessment_id===id);const index=(current.series||[]).findIndex(value=>String(value.timestamp)===String(item?.timestamp));if(index>=0){startIndex=Math.min(startIndex,index);document.getElementById('rangeStart').value=startIndex}renderBreakouts();renderCharts();document.getElementById(`breakout-${id}`)?.scrollIntoView({behavior:'smooth',block:'center'})}
function renderRules(){const target=document.getElementById('ruleList');if(!current){target.innerHTML='<div class="hover-info">没有可展示的条件明细。</div>';document.getElementById('conditionStats').textContent='';return}const rules=current.rule_evaluations||[];let passed=0,failed=0,unavailable=0;for(const rule of rules)for(const condition of(rule.conditions||[])){if(condition.passed===true)passed++;else if(condition.passed===false)failed++;else unavailable++}document.getElementById('conditionStats').textContent=`满足 ${passed} · 未满足 ${failed} · 不可用 ${unavailable}`;target.innerHTML=rules.map(rule=>`<details class="rule" ${rule.triggered?'open':''}><summary>${badge(rule.triggered)}<span class="rule-title">${esc(ruleTitle(rule))}</span><span class="hover-info">${esc(label(rule.direction||rule.outcome))}</span></summary><div class="conditions"><table><thead><tr><th>条件</th><th>实际值</th><th>阈值/对象</th><th>运算</th><th>结果</th><th>相对位置</th><th>影响/权重</th><th>时间</th><th>价格</th></tr></thead><tbody>${(rule.conditions||[]).map(condition=>`<tr><td>${esc(conditionTitle(condition))}</td><td>${esc(fmtAny(condition.actual_value))}</td><td>${esc(fmtAny(condition.reference_value))}</td><td><code>${esc(condition.operator)}</code></td><td>${badge(condition.passed)}</td><td>${esc(label(condition.relative_position))}</td><td>${esc(label(condition.impact))} / ${fmt(condition.weight,2)}</td><td>${esc(shortTime(condition.timestamp))}</td><td>${fmt(condition.price,2)}</td></tr>`).join('')}</tbody></table></div></details>`).join('')||'<div class="hover-info">没有可展示的条件明细。</div>'}
function fmtAny(value){if(Array.isArray(value))return '['+value.map(fmtAny).join(', ')+']';if(value&&typeof value==='object')return JSON.stringify(value);return typeof value==='number'?fmt(value):String(value??'—')}
function ruleTitle(rule){const titles={turtle_20_breakout:'海龟 20 日价格突破',turtle_55_breakout:'海龟 55 日价格突破',sma_10_20_golden_cross:'SMA10/20 金叉',sma_10_20_death_cross:'SMA10/20 死叉',sma_alignment_long:'SMA 多头排列',sma_alignment_short:'SMA 空头排列',ema_trend_long:'EMA 多头趋势',ema_trend_short:'EMA 空头趋势',trend_quality_confirmed:'ADX/DMI 趋势强度确认',atr_normal_range:'ATR 正常波动区间',relative_volume_confirmation:'相对成交量确认',strategy_rating_a:'策略 A 级共振'};if(titles[rule.rule_id])return titles[rule.rule_id];const match=String(rule.rule_id||'').match(/^macd_(D\d+)_(long|short)$/);return match?`${match[1]} MACD ${match[2]==='long'?'多头':'空头'}状态`:label(rule.rule_id||rule.name)}
function conditionTitle(condition){const id=String(condition.condition_id||'');const turtle=id.match(/^turtle_(20|55)\.close_(above_high|below_low)$/);if(turtle)return `收盘价${turtle[2]==='above_high'?'高于':'低于'} ${turtle[1]} 日唐奇安${turtle[2]==='above_high'?'上轨':'下轨'}`;const stack=id.match(/^sma_stack\.(\d+)_(above|below)_(\d+)$/);if(stack)return `SMA${stack[1]} ${stack[2]==='above'?'高于':'低于'} SMA${stack[3]}`;const macd=id.match(/^macd_(D\d+)\.dif_(above|below)_dea$/);if(macd)return `${macd[1]} MACD DIF ${macd[2]==='above'?'高于':'低于'} DEA`;const titles={'sma_cross.current_fast_above_slow':'当前 SMA10 高于 SMA20','sma_cross.previous_fast_not_above_slow':'前一日 SMA10 不高于 SMA20','sma_cross.current_fast_below_slow':'当前 SMA10 低于 SMA20','sma_cross.previous_fast_not_below_slow':'前一日 SMA10 不低于 SMA20','ema_trend.fast_above_slow':'EMA 快线高于慢线','ema_trend.fast_below_slow':'EMA 快线低于慢线','trend_quality.adx_threshold':'ADX 达到趋势确认阈值','volatility.atr_percentile_normal':'ATR 分位处于正常区间','volume.relative_confirmation':'相对成交量达到确认阈值','rating_a.aligned_families':'同向策略族数达到 A 级要求','rating_a.score':'综合评分达到 A 级要求'};return titles[id]||label(condition.name||id)}
function renderIndicators(){const target=document.getElementById('indicatorRows');if(!current){target.innerHTML='<tr><td colspan="4">无指标数据。</td></tr>';return}const checks=current.strategy_snapshot?.strategy_checks||{};const rows=[];const add=(name,value,detail)=>{if(value&&typeof value==='object')rows.push(`<tr><td>${esc(name)}</td><td>${esc(label(value.status||value.grade))}</td><td>${directionTag(value.direction)}</td><td>${esc(detail(value))}</td></tr>`)};add('SMA 均线排列',checks.sma_alignment,value=>`周期 ${(value.periods||[]).join('/')}；${Object.entries(value.values||{}).map(([key,item])=>`SMA${key}=${fmt(item,2)}`).join('，')}`);add('EMA 长周期趋势',checks.ema_trend,value=>`周期 ${(value.periods||[]).join('/')}；${Object.entries(value.values||{}).map(([key,item])=>`EMA${key}=${fmt(item,2)}`).join('，')}`);add('MACD 多周期',checks.macd_summary,value=>`活跃周期：${(value.active_timeframes||[]).join('、')||'无'}；${label(value.direction)}`);Object.entries(checks.macd||{}).forEach(([timeframe,value])=>{if(value&&typeof value==='object')rows.push(`<tr><td>${esc(timeframe+' MACD')}</td><td>${esc(label(value.status))}</td><td>${directionTag(value.direction)}</td><td>DIF=${fmt(value.dif)}，DEA=${fmt(value.dea)}，零轴：${esc(label(value.zero_axis))}，事件：${esc(label(value.event))}</td></tr>`)});add('ADX/DMI 趋势质量',checks.trend_quality,value=>`ADX=${fmt(value.adx,2)}，+DI=${fmt(value.plus_di,2)}，-DI=${fmt(value.minus_di,2)}；${value.confirmed?'已确认':'未确认'}`);add('ATR 波动状态',checks.volatility,value=>`ATR=${fmt(value.atr,4)}，ATR%=${fmt((value.atr_pct??0)*100,2)}%，分位=${fmt((value.percentile??0)*100,1)}%`);add('相对成交量',checks.volume,value=>`相对量=${fmt(value.relative_volume,2)}，基准=${fmt(value.baseline,2)}；${value.confirmed?'已确认':'未确认'}`);add('组合评级',checks.rating,value=>`评分 ${fmt(value.score,1)}；策略族：${Object.entries(value.family_votes||{}).map(([key,item])=>`${label(key)}=${label(item)}`).join('，')}`);target.innerHTML=rows.join('')||'<tr><td colspan="4">指标仍在预热或不可用。</td></tr>'}
function isTurtleSignal(signal){const name=String(signal.indicator_name||signal.indicator||'');const type=String(signal.signal_type||'');return name==='turtle_20'||name==='turtle_55'||type.startsWith('TURTLE_')}
function signalName(signal){const name=signal.indicator_name||signal.indicator||signal.signal_type||signal.event;const event=signal.event||signal.signal_type;return `${label(name)}${event?`：${label(event)}`:''}`}
function renderOtherTables(){const signals=(current?.signals||[]).filter(signal=>!isTurtleSignal(signal));document.getElementById('signalRows').innerHTML=signals.map(signal=>`<tr><td>${esc(shortTime(signal.signal_time||signal.timestamp))}</td><td>${esc(signalName(signal))}</td><td>${directionTag(String(signal.direction||'').toLowerCase())}</td><td>${fmt(signal.trigger_price??signal.price,2)}</td></tr>`).join('')||'<tr><td colspan="4">本次没有均线或 MACD 事件。</td></tr>';const anomalies=current?.anomalies||[];document.getElementById('anomalyRows').innerHTML=anomalies.map(item=>`<tr><td>${esc(shortTime(item.timestamp))}</td><td>${esc(label(item.anomaly_type))}</td><td>${esc(label(item.severity))}</td><td>${esc(anomalySummary(item))}</td></tr>`).join('')||'<tr><td colspan="4">当前可视范围没有异常点。</td></tr>'}
function anomalySummary(item){const titles={large_price_move:'单日价格变动超过阈值',range_expansion:'单日高低价振幅异常扩大',atr_percentile_extreme:'ATR 分位进入极端区间'};return titles[item.anomaly_type]||label(item.anomaly_type||item.summary)}
function renderTechnicalDetails(){const transitions=current?.state_transitions||[];document.getElementById('transitionRows').innerHTML=transitions.map(item=>`<tr><td>${esc(shortTime(item.timestamp))}</td><td>${esc(label(item.state_name))}</td><td>${esc(label(item.from_state))}</td><td>${esc(label(item.to_state))}</td><td>${esc(`${label(item.state_name)}从 ${label(item.from_state)} 变为 ${label(item.to_state)}`)}</td></tr>`).join('')||'<tr><td colspan="5">当前可视范围未发生监控状态变更。</td></tr>';const changes=current?.change_log||[];document.getElementById('changeRows').innerHTML=changes.map(item=>`<tr><td><code>${esc(item.module)}</code></td><td>${esc(item.change)}</td><td>${esc(item.reason)}</td><td>${esc(item.effect)}</td></tr>`).join('')||'<tr><td colspan="4">无技术说明。</td></tr>'}
function renderRaw(){document.getElementById('rawJson').textContent=JSON.stringify(currentRow||{},null,2)}
function legend(id,items){document.getElementById(id).innerHTML=items.map(item=>`<span><i style="background:${palette[item]||'#fff'}"></i>${esc(legendName(item))}</span>`).join('')}
function legendName(item){return {close:'收盘价',channel_high_20:'20 日上轨',channel_low_20:'20 日下轨',channel_high_55:'55 日上轨',channel_low_55:'55 日下轨',sma_10:'SMA10',sma_20:'SMA20',ema_144:'EMA144',ema_169:'EMA169',dif:'DIF',dea:'DEA',adx:'ADX',plus_di:'+DI',minus_di:'-DI',atr_percentile:'ATR 分位',relative_volume:'相对成交量'}[item]||item}
function setupCanvas(id){const canvas=document.getElementById(id),dpr=window.devicePixelRatio||1,width=canvas.clientWidth,height=Number(canvas.getAttribute('height'));if(canvas.width!==Math.floor(width*dpr)||canvas.height!==Math.floor(height*dpr)){canvas.width=Math.floor(width*dpr);canvas.height=Math.floor(height*dpr)}const context=canvas.getContext('2d');context.setTransform(dpr,0,0,dpr,0,0);return {canvas,context,width,height}}
function renderCharts(){const series=current?.series||[];const chartRows=series.slice(startIndex);const range=document.getElementById('rangeLabel');range.textContent=chartRows.length?`${shortTime(chartRows[0].timestamp)} 至 ${shortTime(chartRows[chartRows.length-1].timestamp)}`:'无图表数据';const price=['close','channel_high_20','channel_low_20','channel_high_55','channel_low_55','sma_10','sma_20','ema_144','ema_169'];const macd=['dif','dea'];const trend=['adx','plus_di','minus_di'];const volume=['atr_percentile','relative_volume'];legend('priceLegend',price);legend('macdLegend',macd);legend('trendLegend',trend);legend('volLegend',volume);draw('priceChart',chartRows,price,{candles:true,markers:true});draw('macdChart',chartRows,macd,{});draw('trendChart',chartRows,trend,{});draw('volChart',chartRows,volume,{transform:(key,value)=>key==='atr_percentile'?value*100:value});if(hoverIndex!==null&&chartRows[hoverIndex]){const row=chartRows[hoverIndex];document.getElementById('hoverInfo').textContent=`${shortTime(row.timestamp)} · 收盘 ${fmt(row.close,2)} · ADX ${fmt(row.adx,2)} · ATR 分位 ${fmt((row.atr_percentile??0)*100,1)}% · 相对成交量 ${fmt(row.relative_volume,2)}`}else document.getElementById('hoverInfo').textContent='移动鼠标查看同一时间点；点击突破标记可定位表格。'}
function draw(id,chartRows,keys,options){const {canvas,context,width,height}=setupCanvas(id);context.clearRect(0,0,width,height);const pad={left:50,right:16,top:14,bottom:26};context.font='11px system-ui';const values=[];for(const row of chartRows)for(const key of keys){const value=row[key];if(value!==null&&Number.isFinite(Number(value)))values.push(options.transform?options.transform(key,Number(value)):Number(value))}if(options.candles)for(const row of chartRows)for(const key of ['open','high','low','close'])if(Number.isFinite(Number(row[key])))values.push(Number(row[key]));if(!values.length){context.fillStyle='#8095aa';context.fillText('数据不足',pad.left,pad.top+16);return}let min=Math.min(...values),max=Math.max(...values);if(min===max){min-=1;max+=1}const span=max-min;min-=span*.06;max+=span*.06;const innerWidth=width-pad.left-pad.right,innerHeight=height-pad.top-pad.bottom;const x=index=>pad.left+(chartRows.length<=1?0:index/(chartRows.length-1))*innerWidth;const y=value=>pad.top+(max-value)/(max-min)*innerHeight;for(let line=0;line<4;line++){const yy=pad.top+line*innerHeight/3;context.strokeStyle='#172a3d';context.beginPath();context.moveTo(pad.left,yy);context.lineTo(width-pad.right,yy);context.stroke();context.fillStyle='#8095aa';context.fillText(fmt(max-line*(max-min)/3,2),4,yy+4)}if(options.candles){const body=Math.max(1,Math.min(7,innerWidth/Math.max(1,chartRows.length)*.58));chartRows.forEach((row,index)=>{const open=Number(row.open),high=Number(row.high),low=Number(row.low),close=Number(row.close);if(![open,high,low,close].every(Number.isFinite))return;const color=close>=open?'#4ade80':'#fb7185';const xx=x(index);context.strokeStyle=color;context.fillStyle=color;context.beginPath();context.moveTo(xx,y(high));context.lineTo(xx,y(low));context.stroke();context.fillRect(xx-body/2,Math.min(y(open),y(close)),body,Math.max(1,Math.abs(y(open)-y(close))))})}for(const key of keys){context.strokeStyle=palette[key]||'#fff';context.lineWidth=key==='close'?2:1.25;context.beginPath();let started=false;chartRows.forEach((row,index)=>{let value=row[key];if(value===null||!Number.isFinite(Number(value))){started=false;return}value=options.transform?options.transform(key,Number(value)):Number(value);if(!started){context.moveTo(x(index),y(value));started=true}else context.lineTo(x(index),y(value))});context.stroke()}if(options.markers){drawMarkers(context,chartRows,x,y);drawAnomalies(context,chartRows,x,y)}if(hoverIndex!==null&&chartRows[hoverIndex]){context.strokeStyle='#94a3b8';context.setLineDash([3,4]);context.beginPath();context.moveTo(x(hoverIndex),pad.top);context.lineTo(x(hoverIndex),height-pad.bottom);context.stroke();context.setLineDash([])}canvas.onmousemove=event=>{const rect=canvas.getBoundingClientRect();const index=Math.round(((event.clientX-rect.left-pad.left)/Math.max(1,innerWidth))*(chartRows.length-1));hoverIndex=Math.max(0,Math.min(chartRows.length-1,index));renderCharts()};canvas.onmouseleave=()=>{hoverIndex=null;renderCharts()};if(id==='priceChart')canvas.onclick=event=>{const rect=canvas.getBoundingClientRect();const hit=priceMarkerHits.find(marker=>Math.hypot(event.clientX-rect.left-marker.x,event.clientY-rect.top-marker.y)<12);if(hit)focusAssessment(hit.assessmentId)}}
function drawMarkers(context,chartRows,x,y){priceMarkerHits=[];const byTime=new Map(chartRows.map((row,index)=>[String(row.timestamp),index]));for(const item of(current?.breakout_assessments||[])){const index=byTime.get(String(item.timestamp));if(index===undefined)continue;const price=Number(item.current_price??chartRows[index].close);if(!Number.isFinite(price))continue;const xx=x(index),yy=y(price),color=item.entry_direction==='做多'?'#4ade80':item.entry_direction==='做空'?'#fb7185':'#fbbf24';context.fillStyle=color;context.strokeStyle=item.assessment_id===activeAssessmentId?'#e2e8f0':color;context.lineWidth=item.assessment_id===activeAssessmentId?2:1;context.beginPath();if(item.breakout_type==='向下突破'){context.moveTo(xx,yy+6);context.lineTo(xx-5,yy-4);context.lineTo(xx+5,yy-4)}else{context.moveTo(xx,yy-6);context.lineTo(xx-5,yy+4);context.lineTo(xx+5,yy+4)}context.closePath();context.fill();context.stroke();priceMarkerHits.push({assessmentId:item.assessment_id,x:xx,y:yy})}}
function drawAnomalies(context,chartRows,x,y){const byTime=new Map(chartRows.map((row,index)=>[String(row.timestamp),index]));for(const item of(current?.anomalies||[])){const index=byTime.get(String(item.timestamp));if(index===undefined)continue;const price=Number(item.price??chartRows[index].close);if(!Number.isFinite(price))continue;context.fillStyle='#60a5fa';context.fillRect(x(index)-3,y(price)-3,6,6)}}
select.onchange=()=>load(Number(select.value));document.getElementById('rangeStart').oninput=event=>{startIndex=Number(event.target.value);hoverIndex=null;renderCharts()};window.addEventListener('resize',()=>renderCharts());if(rows.length)load(0);else{document.getElementById('identity').textContent='快照中没有可供展示的标的。'}
"""


__all__ = ["render_daily_dashboard", "write_daily_dashboard", "write_instrument_report"]
